import{_ as t,c as a,o as e,a4 as o}from"./chunks/framework.CpVK_f0P.js";const _=JSON.parse('{"title":"反复出现的问题","description":"","frontmatter":{},"headers":[],"relativePath":"mistakes/recurring-mistakes.md","filePath":"mistakes/recurring-mistakes.md"}'),r={name:"mistakes/recurring-mistakes.md"},n=o('<h1 id="反复出现的问题" tabindex="-1">反复出现的问题 <a class="header-anchor" href="#反复出现的问题" aria-label="Permalink to &quot;反复出现的问题&quot;">​</a></h1><p>记录在多次训练中重复出现的共性问题。</p><h2 id="讲故事时时态混乱" tabindex="-1">讲故事时时态混乱 <a class="header-anchor" href="#讲故事时时态混乱" aria-label="Permalink to &quot;讲故事时时态混乱&quot;">​</a></h2><p>复述一段过去的事情时，经常不自觉地从过去时滑回现在时。例如说 &quot;he doesn&#39;t know&quot; 而不是 &quot;he didn&#39;t know&quot;。</p><p><strong>解决方法</strong>：复述前先在心里确定&quot;这是过去的事&quot;，全程使用过去时。如果发现说错了，立即自我纠正，不要继续说下去。</p><h2 id="忘记使用冠词" tabindex="-1">忘记使用冠词 <a class="header-anchor" href="#忘记使用冠词" aria-label="Permalink to &quot;忘记使用冠词&quot;">​</a></h2><p>经常漏掉 a/an/the。例如说 &quot;met old woman&quot; 而不是 &quot;met an old woman&quot;，说 &quot;go to restaurant&quot; 而不是 &quot;go to the restaurant&quot;。</p><h2 id="一个句子放入太多内容" tabindex="-1">一个句子放入太多内容 <a class="header-anchor" href="#一个句子放入太多内容" aria-label="Permalink to &quot;一个句子放入太多内容&quot;">​</a></h2><p>想说一件事但在句子中途又加入新的信息，导致句子说到一半就乱了。</p><p><strong>解决方法</strong>：一个句子只说一件事。想说多件事就分成多个短句。</p><h2 id="习惯逐字翻译中文" tabindex="-1">习惯逐字翻译中文 <a class="header-anchor" href="#习惯逐字翻译中文" aria-label="Permalink to &quot;习惯逐字翻译中文&quot;">​</a></h2><p>在脑子里先想中文，再一个词一个词翻译成英文，导致语序不自然、表达僵硬。</p><p><strong>解决方法</strong>：用已经会的句式表达。允许意思不完全精确，只要对方能理解就行。</p><h2 id="想不到表达时不愿意使用简单句替代" tabindex="-1">想不到表达时不愿意使用简单句替代 <a class="header-anchor" href="#想不到表达时不愿意使用简单句替代" aria-label="Permalink to &quot;想不到表达时不愿意使用简单句替代&quot;">​</a></h2><p>遇到不会说的词或句式时，倾向于卡住或放弃，而不是换成更简单的说法。</p><p><strong>解决方法</strong>：接受&quot;说出来&quot;比&quot;说得完美&quot;更重要。主动降级成简单句。</p>',16),s=[n];function i(u,h,d,c,l,p){return e(),a("div",null,s)}const m=t(r,[["render",i]]);export{_ as __pageData,m as default};
